  "DESCRIPTION": "Animated moiré pattern with simulated CRT scanlines, subpixel (phosphor) layout, curvature and bloom."
}
*/

#ifdef GL_ES
precision mediump float;
#endif


#define PI 3.14159265

// ----------------------------------------------------------------------
// Compute the basic moiré pattern for each color channel.
// We “simulate” a CRT phosphor layout by sampling the pattern
// with slight horizontal offsets for R, G and B.
vec3 moirePattern(vec2 uv, float time, float pixelSize)
{
    // Offsets for a red-green-blue stripe arrangement:
    vec2 uvR = uv + vec2(pixelSize*0.5, 0.0141);
    vec2 uvG = uv;
    vec2 uvB = uv - vec2(pixelSize*0.5, 0.0141);

    // Two interfering sine waves at slightly different angles:
    float freq = 180.0;
    float angle1 = 0.3313;
    float angle2 = -0.3313;

    float pR = sin( freq * (uvR.x*cos(angle1) + uvR.y*sin(angle1)) + iTime )
             * sin( freq * (uvR.x*cos(angle2) + uvR.y*sin(angle2)) + iTime );

    float pG = sin( freq * (uvG.x*cos(angle1) + uvG.y*sin(angle1)) + iTime )
             * sin( freq * (uvG.x*cos(angle2) + uvG.y*sin(angle2)) + iTime );

    float pB = sin( freq * (uvB.x*cos(angle1) + uvB.y*sin(angle1)) + iTime )
             * sin( freq * (uvB.x*cos(angle2) + uvB.y*sin(angle2)) + iTime );

    return vec3(pR, pG, pB);
}

// ----------------------------------------------------------------------
// A simple scanline mask – darkening alternate horizontal lines.
float scanlineMask(vec2 fragCoord)
{
    // We use the pixel coordinate so that the scan frequency is roughly constant.
    float scan = sin(fragCoord.y * PI * 1.5 / iResolution.y) * 0.1 + 0.5;
    // Darken the dark lines and leave the bright ones intact.
    return mix(0.3, 1.0, scan);
}

// ----------------------------------------------------------------------
// Apply a simple barrel distortion to mimic the slight curvature of a CRT.
vec2 applyCurvature(vec2 uv)
{
    // Center coordinates about 0.5:
    vec2 centered = uv - 0.5;
    float dist = length(centered);
    // The curvature factor (adjust k to taste):
    float k = 0.15;
    centered *= (1.0 + k * dist * dist);
    return centered + 0.5;
}

// ----------------------------------------------------------------------
// A simple “bloom” approximation by sampling nearby offsets.
vec3 applyBloom(vec2 uv, float time, float pixelSize)
{
    vec3 sum = vec3(0.0);
    const int samples = 8;
    for (int i = 0; i < samples; i++)
    {
        // Distribute sample directions in a circle:
        float angle = 6.2831853 * float(i) / float(samples);
        vec2 offset = vec2(cos(angle), sin(angle)) * pixelSize * 2.0;
        vec3 sampler = moirePattern(uv + offset, time, pixelSize);
        sum += sampler;
    }
    return sum / float(samples);
}

// ----------------------------------------------------------------------
// Main rendering function.
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalize coordinates to [0,1] and adjust for aspect ratio:
    vec2 uv = fragCoord.xy / iResolution.xy;
    uv.x *= iResolution.x / iResolution.y;

    // Apply CRT curvature:
    uv = applyCurvature(uv);

    // Define an approximate pixel size (adjust to taste):
    float pixelSize = 1.0 / 600.0;

    // Compute the base moiré pattern with subpixel (phosphor) offsets:
    vec3 color = moirePattern(uv, iTime, pixelSize);

    // Apply scanline effect using the fragment coordinate:
    color *= scanlineMask(fragCoord.xy);

    // Compute a crude bloom by sampling neighbors:
    vec3 bloom = applyBloom(uv, iTime, pixelSize);
    // Mix a little bloom into the base color:
    color = mix(color, color + bloom, 0.3);

    // Gamma correction (approximate):
    color = pow(color, vec3(0.4545));

    fragColor = vec4(color, 1.0);
}
